-- Jovan Pets: esquema inicial PostgreSQL. Aplicar una vez sobre una BD vacia.
-- Las entidades Java son la referencia; el perfil postgres usa ddl-auto=validate.
BEGIN;
CREATE TABLE cliente (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(120) NOT NULL,cedula VARCHAR(30) UNIQUE,telefono VARCHAR(255),email VARCHAR(255),direccion VARCHAR(255),activo BOOLEAN NOT NULL);
CREATE TABLE usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,email VARCHAR(180) NOT NULL UNIQUE,clave_hash VARCHAR(255) NOT NULL,rol VARCHAR(255) NOT NULL CHECK(rol IN ('CLIENTE','PERSONAL','ADMINISTRADOR')),activo BOOLEAN NOT NULL,cliente_id BIGINT UNIQUE REFERENCES cliente(id));
CREATE TABLE mascota (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,especie VARCHAR(255) NOT NULL,raza VARCHAR(255),sexo VARCHAR(255),fecha_nacimiento DATE,peso NUMERIC(10,2),propietario_id BIGINT NOT NULL REFERENCES cliente(id),activo BOOLEAN NOT NULL);
CREATE TABLE atencion (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mascota_id BIGINT NOT NULL REFERENCES mascota(id),tipo VARCHAR(255) NOT NULL CHECK(tipo IN ('ANTECEDENTE','CONTROL','VACUNA','DESPARASITACION')),fecha DATE NOT NULL,descripcion VARCHAR(4000) NOT NULL,profesional VARCHAR(255),proxima_fecha DATE);
CREATE TABLE servicio (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,descripcion VARCHAR(2000),categoria VARCHAR(255) NOT NULL,precio NUMERIC(14,2) NOT NULL,duracion_minutos INTEGER NOT NULL,activo BOOLEAN NOT NULL);
CREATE TABLE agenda (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE cita (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mascota_id BIGINT NOT NULL REFERENCES mascota(id),servicio_id BIGINT NOT NULL REFERENCES servicio(id),inicio TIMESTAMP NOT NULL,fin TIMESTAMP NOT NULL,estado VARCHAR(255) NOT NULL CHECK(estado IN ('PENDIENTE','CONFIRMADA','RECHAZADA','CANCELADA','ATENDIDA')),motivo VARCHAR(1000));
CREATE TABLE producto (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nombre VARCHAR(255) NOT NULL,descripcion VARCHAR(2000),categoria VARCHAR(255) NOT NULL,precio NUMERIC(14,2) NOT NULL CHECK(precio>0),stock INTEGER NOT NULL CHECK(stock>=0),stock_minimo INTEGER NOT NULL CHECK(stock_minimo>=0),activo BOOLEAN NOT NULL);
CREATE TABLE movimiento_inventario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,producto_id BIGINT NOT NULL REFERENCES producto(id),fecha TIMESTAMP NOT NULL,tipo VARCHAR(255) NOT NULL CHECK(tipo IN ('ENTRADA','SALIDA')),cantidad INTEGER NOT NULL CHECK(cantidad>0),motivo VARCHAR(500) NOT NULL,saldo INTEGER NOT NULL CHECK(saldo>=0));
CREATE TABLE pedido (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cliente_id BIGINT NOT NULL REFERENCES cliente(id),fecha TIMESTAMP NOT NULL,estado VARCHAR(255) NOT NULL CHECK(estado IN ('PENDIENTE','EN_PREPARACION','LISTO_RECOGER','DESPACHADO','ENTREGADO','CANCELADO')),modalidad VARCHAR(255) NOT NULL CHECK(modalidad IN ('RECOGIDA','DOMICILIO')),direccion_entrega VARCHAR(255),total NUMERIC(14,2) NOT NULL);
CREATE TABLE detalle_pedido (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,pedido_id BIGINT NOT NULL REFERENCES pedido(id),producto_id BIGINT NOT NULL REFERENCES producto(id),nombre_producto VARCHAR(255) NOT NULL,cantidad INTEGER NOT NULL CHECK(cantidad>0),precio_unitario NUMERIC(14,2) NOT NULL,subtotal NUMERIC(14,2) NOT NULL);
CREATE INDEX ix_mascota_propietario ON mascota(propietario_id);
CREATE INDEX ix_atencion_mascota_fecha ON atencion(mascota_id,fecha);
CREATE INDEX ix_cita_intervalo ON cita(inicio,fin);
CREATE INDEX ix_movimiento_producto_fecha ON movimiento_inventario(producto_id,fecha);
CREATE INDEX ix_pedido_cliente_fecha ON pedido(cliente_id,fecha);
INSERT INTO agenda(nombre) VALUES ('VETERINARIA'),('PELUQUERIA');
COMMIT;
